    public struct BoardEpic: Codable, Sendable, Equatable {
        public var criteria: [EpicCriterion]
        /// What stops the epic from moving to done; both empty means it can
        public var doneBlockers: DoneBlockers
        public var epic: Epic
        public var objective: Swift.String?
        /// The epic's final review ticket, once it exists
        public var review: WorkTicket?

        /// What stops the epic from moving to done; both empty means it can
        public struct DoneBlockers: Codable, Sendable, Equatable {
            /// Ticket keys not done or canceled
            public var openTickets: [Swift.String]
            /// Criterion positions
            public var uncheckedCriteria: [Swift.Int]

            public init(
                openTickets: [Swift.String],
                uncheckedCriteria: [Swift.Int]
            ) {
                self.openTickets = openTickets
                self.uncheckedCriteria = uncheckedCriteria
            }

