    public struct ChatCodeChange: Codable, Sendable, Equatable {
        public var additions: Swift.Int
        /// Binary files have no patch
        public var binary: Swift.Bool
        public var deletions: Swift.Int
        /// The path before a rename
        public var oldPath: Swift.String?
        /// The file's unified diff hunks (from the first @@ line; no diff --git header), at most 40 KB; absent for binary files or when the turn's total budget (200 KB) ran out
        public var patch: Swift.String?
        /// Repository-relative path after the change
        public var path: Swift.String
        /// Repository URL for this change
        public var repository: Swift.String?
        public var status: Status
        /// The patch was cut short or left out to stay within the limits
        public var truncated: Swift.Bool

        public struct Status: APIStringEnum {
            public let rawValue: Swift.String
            public init(rawValue: Swift.String) { self.rawValue = rawValue }
            public static let added = Status(rawValue: "added")
            public static let modified = Status(rawValue: "modified")
            public static let deleted = Status(rawValue: "deleted")
            public static let renamed = Status(rawValue: "renamed")
            public static let allKnown: [Status] = [added, modified, deleted, renamed]
        }

        public init(
            additions: Swift.Int,
            binary: Swift.Bool,
            deletions: Swift.Int,
            oldPath: Swift.String? = nil,
            patch: Swift.String? = nil,
            path: Swift.String,
            repository: Swift.String? = nil,
            status: Status,
            truncated: Swift.Bool
        ) {
            self.additions = additions
            self.binary = binary
            self.deletions = deletions
            self.oldPath = oldPath
            self.patch = patch
            self.path = path
            self.repository = repository
            self.status = status
            self.truncated = truncated
        }

        enum CodingKeys: Swift.String, CodingKey {
            case additions
            case binary
            case deletions
            case oldPath = "old_path"
            case patch
            case path
            case repository
            case status
            case truncated
        }

        public init(from decoder: any Decoder) throws {
            let c = try decoder.container(keyedBy: CodingKeys.self)
            self.additions = try c.decode(Swift.Int.self, forKey: .additions)
            self.binary = try c.decode(Swift.Bool.self, forKey: .binary)
            self.deletions = try c.decode(Swift.Int.self, forKey: .deletions)
            self.oldPath = try c.decodeIfPresent(Swift.String.self, forKey: .oldPath)
            self.patch = try c.decodeIfPresent(Swift.String.self, forKey: .patch)
            self.path = try c.decode(Swift.String.self, forKey: .path)
            self.repository = try c.decodeIfPresent(Swift.String.self, forKey: .repository)
            self.status = try c.decode(Status.self, forKey: .status)
            self.truncated = try c.decode(Swift.Bool.self, forKey: .truncated)
        }

        public func encode(to encoder: any Encoder) throws {
            var c = encoder.container(keyedBy: CodingKeys.self)
            try c.encode(additions, forKey: .additions)
