    public struct ChatSession: Codable, Sendable, Equatable {
        public var agent: AgentRef
        /// Set on a thread (an aside anchored to a message): the parent chat's message it is about
        public var anchorMessageId: Swift.String?
        public var archived: Swift.Bool
        /// The model is routed per turn: a fresh session starts on the tier the message calls for, and a running one only moves up. Picking a model turns it off.
        public var autoModel: Swift.Bool?
        /// Per-chat auto-compaction threshold in context tokens (0 disables auto-compaction; null inherits the server default)
        public var autoRolloverTokens: APINullable<Swift.Int>?
        /// The address picked for this chat's commits. Absent until one is picked, or once it is no longer one of the creator's emails; commits then use their primary email.
        public var commitEmail: Swift.String?
        /// Optional user focus note saved with /compact for the next turn
        public var compactFocus: Swift.String?
        /// Set after /compact; the next turn starts a fresh context window with handoff + workspace git brief
        public var compactPending: Swift.Bool?
        /// Current segment's last reported context window size in tokens
        public var contextTokens: Swift.Int?
        public var createdAt: Swift.String
        /// The run serving the current harness segment; its events show live activity
        public var currentRunId: Swift.String?
        /// Reasoning effort; absent means the harness's own default
        public var effort: ChatEffort?
        /// Why the last turn failed
        public var error: Swift.String?
        /// Source chat this conversation was forked from
        public var forkedFromChatId: APINullable<Swift.String>?
        /// Fork anchor message in the source chat
        public var forkedFromMessageId: APINullable<Swift.String>?
        public var harness: Harness
        public var id: Swift.String
        public var lastMessageAt: Swift.String?
        public var messageCount: Swift.Int
        /// The model the next turn uses
        public var model: Swift.String
        /// Set on an aside: the chat whose running reply it answers a question about
        public var parentChatId: Swift.String?
        /// Every persona in the chat: the host first, then the ones mentioned in (by @name or an approved proposal), in the order they joined
        public var participants: [PersonaSummary]?
        /// Repository selected for the next turn while a reply is running
        public var pendingRepoUrl: Swift.String?
        /// What a chat needs to render its persona. Absent on a chat means the built-in Assistant.
        public var persona: PersonaSummary?
        /// The start of the newest reply as plain text; only when listing one space's chats
        public var preview: Swift.String?
        /// Key of the attached project; absent when none is attached
        public var project: Swift.String?
        /// The active repository; other attached checkouts are preserved when it changes.
        public var repoUrl: Swift.String?
        public var repositories: [ChatRepository]?
        public var revision: Swift.Int
        /// Set on a second-opinion aside: a read-only critique on a chosen harness/model with the conversation and branch diff snapshot
        public var secondOpinion: Swift.Bool?
        /// The space a chat is in, as the chat shows it
        public var space: ChatSpaceRef?
        /// What a chat needs to render its persona. Absent on a chat means the built-in Assistant.
        public var speaker: PersonaSummary?
        /// idle: waiting for the person; running: a turn is queued or executing; failed: the last turn failed (posting again retries)
        public var state: ChatState
        /// A temporary chat: it doesn't use the person's memory or past chats, stays out of search, and is deleted after a day without messages
        public var temporary: Swift.Bool?
        /// Defaults to the start of the first message
        public var title: Swift.String
        /// Assistant replies newer than the person's read position (POST /chats/{id}/read)
        public var unread: Swift.Int
        public var updatedAt: Swift.String
        /// The branches the coding persona pushed in this chat, oldest first (feat/..., fix/..., chore/...). It makes them as changes are asked for, so a new chat has none. Absent when the chat has no repository.
        public var workBranches: [Swift.String]?
        /// The folder on the person's machine holding the current run's checkout, while it exists; absent for a checkout on the run's disk image inside the microVM
        public var workspacePath: Swift.String?

        public init(
