    public struct DelegationEfficiency: Codable, Sendable, Equatable {
        public var agentId: Swift.String
        /// Mean checks time over delegated runs that have timings
        public var avgChecksSeconds: Swift.Double
        /// Mean harness time over delegated runs that have timings
        public var avgHarnessSeconds: Swift.Double
        /// Mean elapsed time of a delegated run
        public var avgSeconds: Swift.Double
        /// Mean setup time over delegated runs that have timings
        public var avgSetupSeconds: Swift.Double
        /// Times the server sent a mechanical check failure back to the sub agent before waking the main agent, summed over its runs
        public var bounces: Swift.Int
        /// Delegated runs the runner checked (older runs were never checked)
        public var checked: Swift.Int
        public var childCostUsdMicros: Swift.Int
        /// Finished delegated runs
        public var delegations: Swift.Int
        /// Runs whose result passed the runner's checks on the first attempt (the server never sent a check failure back) and needed no repeat delegation to the same agent
        public var firstPass: Swift.Int
        /// first_pass / checked, 0 to 1; 0 when nothing was checked
        public var firstPassRate: Swift.Double
        public var handle: Swift.String
        public var name: Swift.String
        /// Main-agent run cost attributed to this agent: each parent run's cost is split evenly by count across its child runs, and this sums the shares of this agent's children
        public var parentCostUsdMicros: Swift.Int
        /// Runs followed by another delegation to the same agent under the same parent run
        public var repairLoops: Swift.Int
        public var totalCostUsdMicros: Swift.Int

        public init(
            agentId: Swift.String,
            avgChecksSeconds: Swift.Double,
            avgHarnessSeconds: Swift.Double,
            avgSeconds: Swift.Double,
            avgSetupSeconds: Swift.Double,
