            checked: Swift.Int,
            childCostUsdMicros: Swift.Int,
            delegations: Swift.Int,
            firstPass: Swift.Int,
            firstPassRate: Swift.Double,
            handle: Swift.String,
            name: Swift.String,
            parentCostUsdMicros: Swift.Int,
            repairLoops: Swift.Int,
            totalCostUsdMicros: Swift.Int
        ) {
            self.agentId = agentId
            self.avgChecksSeconds = avgChecksSeconds
            self.avgHarnessSeconds = avgHarnessSeconds
            self.avgSeconds = avgSeconds
            self.avgSetupSeconds = avgSetupSeconds
            self.bounces = bounces
            self.checked = checked
            self.childCostUsdMicros = childCostUsdMicros
            self.delegations = delegations
            self.firstPass = firstPass
            self.firstPassRate = firstPassRate
            self.handle = handle
            self.name = name
            self.parentCostUsdMicros = parentCostUsdMicros
            self.repairLoops = repairLoops
            self.totalCostUsdMicros = totalCostUsdMicros
        }

        enum CodingKeys: Swift.String, CodingKey {
            case agentId = "agent_id"
            case avgChecksSeconds = "avg_checks_seconds"
