    public struct HarnessActivity: Codable, Sendable, Equatable {
        /// The harness has the credential its runs need (its harness key secret), or the runner needs none. The sidebar shows only connected harnesses.
        public var connected: Swift.Bool
        /// claude-code, codex or antigravity
        public var harness: Swift.String
        public var label: Swift.String
        /// Present while the harness is out of allowance; runs fall back to another harness until then
        public var limitedUntil: Swift.String?
        /// Subscription name when the CLI reports one (max, pro, plus…)
        public var plan: Swift.String?
        /// Runs and chat turns working on this harness now
        public var running: Swift.Int
        /// False when plan limits don't apply or can't be read (API key, signed out, or no reading yet)
        public var usageAvailable: Swift.Bool
        /// When the windows were read; absent before the first reading
        public var usageCheckedAt: Swift.String?
        /// A usage check is in flight; a newer reading may arrive on a later poll
        public var usageChecking: Swift.Bool
        /// Session first, then weekly; windows that renewed since the reading are left out
        public var windows: [UsageWindow]

        public init(
            connected: Swift.Bool,
            harness: Swift.String,
            label: Swift.String,
            limitedUntil: Swift.String? = nil,
            plan: Swift.String? = nil,
            running: Swift.Int,
            usageAvailable: Swift.Bool,
            usageCheckedAt: Swift.String? = nil,
            usageChecking: Swift.Bool,
            windows: [UsageWindow]
        ) {
            self.connected = connected
            self.harness = harness
            self.label = label
            self.limitedUntil = limitedUntil
            self.plan = plan
            self.running = running
            self.usageAvailable = usageAvailable
            self.usageCheckedAt = usageCheckedAt
            self.usageChecking = usageChecking
            self.windows = windows
        }

        enum CodingKeys: Swift.String, CodingKey {
            case connected
            case harness
            case label
            case limitedUntil = "limited_until"
            case plan
            case running
            case usageAvailable = "usage_available"
            case usageCheckedAt = "usage_checked_at"
            case usageChecking = "usage_checking"
            case windows
        }

        public init(from decoder: any Decoder) throws {
            let c = try decoder.container(keyedBy: CodingKeys.self)
            self.connected = try c.decode(Swift.Bool.self, forKey: .connected)
            self.harness = try c.decode(Swift.String.self, forKey: .harness)
            self.label = try c.decode(Swift.String.self, forKey: .label)
            self.limitedUntil = try c.decodeIfPresent(Swift.String.self, forKey: .limitedUntil)
            self.plan = try c.decodeIfPresent(Swift.String.self, forKey: .plan)
            self.running = try c.decode(Swift.Int.self, forKey: .running)
            self.usageAvailable = try c.decode(Swift.Bool.self, forKey: .usageAvailable)
            self.usageCheckedAt = try c.decodeIfPresent(Swift.String.self, forKey: .usageCheckedAt)
            self.usageChecking = try c.decode(Swift.Bool.self, forKey: .usageChecking)
            self.windows = try c.decodeIfPresent([UsageWindow].self, forKey: .windows) ?? []
        }

        public func encode(to encoder: any Encoder) throws {
            var c = encoder.container(keyedBy: CodingKeys.self)
            try c.encode(connected, forKey: .connected)
            try c.encode(harness, forKey: .harness)
            try c.encode(label, forKey: .label)
            try c.encodeIfPresent(limitedUntil, forKey: .limitedUntil)
            try c.encodeIfPresent(plan, forKey: .plan)
            try c.encode(running, forKey: .running)
            try c.encode(usageAvailable, forKey: .usageAvailable)
            try c.encodeIfPresent(usageCheckedAt, forKey: .usageCheckedAt)
            try c.encode(usageChecking, forKey: .usageChecking)
            try c.encode(windows, forKey: .windows)
        }
    }

