        public var endedAt: Swift.String?
        public var harness: Swift.String
        /// Cumulative harness process time across all turns, in milliseconds; absent if not timed
        public var harnessMs: Swift.Int?
        /// Consecutive times this run has been held at a provider limit
        public var holdAttempts: Swift.Int?
        /// waiting_for_quota: hold_until is the provider's stated reset time, not a backoff
        public var holdResetKnown: Swift.Bool?
        /// waiting_for_quota: when the run next tries to resume
        public var holdUntil: Swift.String?
        public var id: Swift.String
        public var inputTokens: Swift.Int
        public var mode: Mode
        public var model: Swift.String
        public var outcome: Swift.String?
        public var outputTokens: Swift.Int
