        public var ticketKey: Swift.String
        public var toolCalls: Swift.Int
        /// Reported input not served from cache
        public var uncachedInputTokens: Swift.Int?
        /// Input whose cache breakdown was not reported
        public var unreportedInputTokens: Swift.Int?
        /// delegation: waiting for a sub agent the run delegated to; checks: a delegated run that finished, waiting for the server to check its result; mockup_review: waiting for a person to review a UI mockup
        public var waitReason: WaitReason?
